{
  "implementation": "def solve(case):
    nodes = case["nodes"]
    core = case["core_distance"]
    distances = case["distances"]
    edges = []
    for d in distances:
        n1, n2, dist = d
        m = max(core[n1], core[n2], dist)
        if n1 <= n2:
            edges.append((m, n1, n2))
        else:
            edges.append((m, n2, n1))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total = 0.0
    for weight, n1, n2 in edges:
        if union(n1, n2):
            mst_edges.append([n1, n2, weight])
            total += weight
            if len(mst_edges) == len(nodes)-1:
                break
    return {"mst_edges": mst_edges, "total_weight": total}"
}
